import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor tanh_forward(torch::Tensor x);
"""

tanh_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fast tanh using fast-math intrinsics, clamped for numerical stability.
__device__ __forceinline__ float fast_tanhf(float x)
{
  // tanh(x) = (e^{2x} - 1) / (e^{2x} + 1); tanh saturates to +/-1 for |x| > ~9.
  const float xc = fminf(fmaxf(x, -10.0f), 10.0f);
  const float e = __expf(2.0f * xc);
  return __fdividef(e - 1.0f, e + 1.0f);
}
template <int Threads>
__global__ void tanh_kernel_cute(const float* __restrict__ X,
                                 float* __restrict__ Y,
                                 int64_t N,
                                 int64_t N4,
                                 int rem)
{
  // Vectorized view over float4 elements using CuTe tensors.
  Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X)),
                           make_shape(N4));
  Tensor mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y)),
                           make_shape(N4));
  const int64_t stride = (int64_t)gridDim.x * Threads;
  // Unrolled grid-stride loop: each thread issues two independent float4
  // loads per iteration, doubling memory-level parallelism per thread.
  // With registers at only ~39/thread there is ample headroom, and the
  // extra in-flight loads push DRAM utilization closer to peak on this
  // memory-bound kernel. Coalescing is preserved: the two accesses per
  // thread are `stride` apart, so each warp still touches two fully
  // contiguous segments per iteration.
  const int64_t tid = (int64_t)blockIdx.x * Threads + threadIdx.x;
  int64_t idx = tid;
  for (; idx + stride < N4; idx += 2 * stride) {
    float4 a = mX4(idx);
    float4 b = mX4(idx + stride);
    a.x = fast_tanhf(a.x);
    a.y = fast_tanhf(a.y);
    a.z = fast_tanhf(a.z);
    a.w = fast_tanhf(a.w);
    b.x = fast_tanhf(b.x);
    b.y = fast_tanhf(b.y);
    b.z = fast_tanhf(b.z);
    b.w = fast_tanhf(b.w);
    mY4(idx) = a;
    mY4(idx + stride) = b;
  }
  if (idx < N4) {
    float4 v = mX4(idx);
    v.x = fast_tanhf(v.x);
    v.y = fast_tanhf(v.y);
    v.z = fast_tanhf(v.z);
    v.w = fast_tanhf(v.w);
    mY4(idx) = v;
  }
  // Scalar tail: rem < 4 elements, handled entirely by block 0.
  if (blockIdx.x == 0 && rem > 0) {
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));
    for (int r = threadIdx.x; r < rem; r += Threads) {
      const int64_t idx = N4 * 4 + r;
      mY(idx) = fast_tanhf(mX(idx));
    }
  }
}

torch::Tensor tanh_forward(torch::Tensor x)
{
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  const int64_t N = x_c.numel();
  if (N == 0) {
    return y;
  }

  const float* X = x_c.data_ptr<float>();
  float* Y = y.data_ptr<float>();

  // Occupancy tuning: profiling shows 100% theoretical occupancy but only
  // ~85% achieved occupancy at 256 threads/block. Using 128-thread blocks
  // doubles the number of independently schedulable resident blocks per SM,
  // reducing warp-scheduling quantization and execution imbalance while
  // preserving fully coalesced float4 accesses for this DRAM-bound kernel.
  constexpr int Threads = 128;
  const int64_t N4 = N / 4;
  const int rem = (int)(N - N4 * 4);
  // Persistent grid-stride sizing: query real per-SM residency and launch an
  // exact whole number of waves so this memory-bound kernel has no partial-wave tail.
  int num_sms = 0;
  cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount,
                         (int)x_c.get_device());
  if (num_sms < 1) num_sms = 1;
  int blocks_per_sm = 0;
  const cudaError_t occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &blocks_per_sm, tanh_kernel_cute<Threads>, Threads, 0);
  if (occ_err != cudaSuccess || blocks_per_sm < 1) {
    (void)cudaGetLastError();
    blocks_per_sm = 2048 / Threads;
  }
  const int64_t fill_grid = (int64_t)num_sms * blocks_per_sm;
  const int64_t work_grid = N4 > 0 ? (N4 + Threads - 1) / Threads : 1;
  const int64_t grid = fill_grid < work_grid ? fill_grid : work_grid;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  tanh_kernel_cute<Threads><<<(unsigned)grid, Threads, 0, stream>>>(
      X, Y, N, N4, rem);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "tanh_kernel_cute launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=tanh_cpp_decl,
    cuda_sources=tanh_cuda_src,
    functions=["tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Tanh activation implemented with a single custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.tanh_forward(x)

